namespace HdrPilot {
// Version choices exist independently of the selected game's installed files.
public sealed class LibraryPanel {
 readonly Window owner;readonly Game game;readonly Func<int> series;readonly Action changed;readonly StackPanel panel=new StackPanel{Name="ComponentLibrary",HorizontalAlignment=HorizontalAlignment.Stretch};
 readonly TextBlock status;readonly List<Action> scans=new List<Action>();readonly List<Func<Task>> refreshers=new List<Func<Task>>();bool working,loaded;
 static string L(string text){return Appearance.Localize(text);}
 static string Version(string value){return (value??"").Replace(",",".").Replace(" ","");}
 static string AutoLabel{get{return RenoNr.T("Destinazione automatica","Automatic destination","Destino automático","Destination automatique","Automatisches Ziel","Destino automático");}}
 static string RestoreLabel{get{return RenoNr.T("Ripristina DLL originali","Restore original DLLs","Restaurar DLL originales","Restaurer les DLL originales","Original-DLLs wiederherstellen","Restaurar DLLs originais");}}
 static string AutoHelp{get{return RenoNr.T("Destinazione non univoca: verifica l’eseguibile selezionato. Nessun file sarà modificato.","Ambiguous destination: check the selected executable. No files will be changed.","Destino ambiguo: comprueba el ejecutable seleccionado. No se modificarán archivos.","Destination ambiguë : vérifiez l’exécutable sélectionné. Aucun fichier ne sera modifié.","Ziel nicht eindeutig: ausgewählte EXE prüfen. Keine Dateien werden geändert.","Destino ambíguo: confira o executável selecionado. Nenhum arquivo será alterado.");}}
 public static string ActionGuide{get{return RenoNr.T("Ripristino e rimozione sono sotto Installa nel riquadro del componente. Un solo pulsante ripristina tutte le copie gestite del componente, nei rispettivi percorsi. File e backup vengono verificati prima di modificare qualsiasi copia. La fila Rimozione in fondo è stata eliminata.","Restore and removal are below Install in each component card. One button restores all managed copies of the component to their respective paths. Files and backups are checked before any copy is modified. The bottom Removal row has been removed.","Restaurar y quitar están debajo de Instalar en cada panel. Un botón restaura todas las copias gestionadas del componente en sus rutas. Se verifican archivos y copias de seguridad antes de modificar nada. Se eliminó la fila inferior de eliminación.","Restaurer et retirer se trouvent sous Installer dans chaque carte. Un bouton restaure toutes les copies gérées du composant dans leurs chemins respectifs. Fichiers et sauvegardes sont vérifiés avant toute modification. La rangée de suppression en bas a été retirée.","Wiederherstellen und Entfernen stehen unter Installieren in jeder Komponentenkarte. Eine Schaltfläche stellt alle verwalteten Kopien der Komponente an ihren jeweiligen Pfaden wieder her. Dateien und Sicherungen werden vor jeder Änderung geprüft. Die untere Entfernen-Leiste wurde entfernt.","Restaurar e remover ficam abaixo de Instalar em cada painel. Um botão restaura todas as cópias gerenciadas do componente nos respectivos caminhos. Arquivos e backups são verificados antes de qualquer alteração. A linha inferior de remoção foi eliminada.");}}
 public static string AutoGuide{get{return ActionGuide+"\n\n"+RenoNr.T("Novità DLL: scegli la versione dal menu; il catalogo online seleziona la più recente disponibile. La destinazione è automatica: priorità alla cartella dell’eseguibile, poi all’unica cartella rilevata; copie storage e backup escluse. Se restano più destinazioni, verifica l’eseguibile. Ripristina DLL originali recupera i file salvati prima del primo aggiornamento con l’app; potrebbero già contenere mod. Senza backup usa la verifica file del launcher.","DLL update: choose a version from the menu; the online catalog selects the latest available. Destination is automatic: executable folder first, then the only detected folder; storage and backup copies excluded. If ambiguous, check the executable. Restore original DLLs recovers files saved before the first app update; these may already contain mods. Without a backup, use the launcher's file verification.","DLL: elige versión; el catálogo selecciona la más reciente. Destino automático: carpeta del ejecutable o única carpeta detectada, sin storage ni copias. Si hay ambigüedad, revisa el ejecutable. Restaurar recupera el estado anterior al primer cambio, que puede contener mods. Sin copia, verifica archivos desde el lanzador.","DLL : choisissez la version ; le catalogue sélectionne la plus récente. Destination automatique : dossier de l’exécutable ou seul dossier détecté, hors storage et sauvegardes. En cas d’ambiguïté, vérifiez l’exécutable. Restaurer récupère l’état avant la première modification, pouvant contenir des mods. Sans sauvegarde, vérifiez les fichiers via le lanceur.","DLLs: Version wählen; der Katalog wählt die neueste. Automatisches Ziel: EXE-Ordner oder einziger erkannter Ordner, ohne Storage und Sicherungen. Bei Mehrdeutigkeit EXE prüfen. Wiederherstellen lädt den Zustand vor der ersten Änderung, eventuell mit Mods. Ohne Sicherung Dateien im Launcher prüfen.","DLLs: escolha a versão; o catálogo seleciona a mais recente. Destino automático: pasta do executável ou única pasta detectada, sem storage e backups. Se ambíguo, confira o executável. Restaurar recupera o estado anterior à primeira alteração, que pode conter mods. Sem backup, verifique arquivos pelo launcher.");}}
 static string Installed{get{return RenoNr.T("Versione installata","Installed version","Versión instalada","Version installée","Installierte Version","Versão instalada");}}
 static string Selection{get{return RenoNr.T("Versione da installare","Version to install","Versión para instalar","Version à installer","Zu installierende Version","Versão para instalar");}}
 public FrameworkElement View {get{return panel;}}
 public LibraryPanel(Window owner,Game game,Func<int> series,Action changed){this.owner=owner;this.game=game;this.series=series;this.changed=changed;
  panel.ToolTip=L("Choose a version, then install. Downloads, signature checks and backups run here. Updates require an existing game integration.");
  status=Dialogs.Text(L("Local catalog ready. Checking online…"),13);panel.Children.Add(status);
  for(int i=0;i<DlssLibraries.Names.Length;i++)Native(DlssLibraries.Names[i],new[]{"Super Resolution","Ray Reconstruction","Frame Generation"}[i]);
  StreamlineCard();NrCard();foreach(var box in panel.Children.OfType<Border>()){var body=box.Child as StackPanel;if(body==null)continue;foreach(var exp in body.Children.OfType<Expander>().ToArray()){body.Children.Remove(exp);body.Children.Add(exp);}}LayoutCards.Group(panel);SavedCard();LayoutCards.Style(panel);
  var refresh=Button(panel,"Refresh catalog",async()=>{if(working)return;working=true;refreshStatus();try{foreach(var run in refreshers)await run();foreach(var scan in scans)scan();status.Text=L("Catalog check completed. See each component for its status.");}finally{working=false;}});
  panel.Loaded+=async(s,e)=>{if(loaded)return;loaded=true;foreach(var run in refreshers)await run();status.Text=L("Catalog check completed. See each component for its status.");};
 }
 void SavedCard(){var body=new StackPanel();var box=new Border{Child=body,Padding=new Thickness(16),Margin=new Thickness(0,0,10,10),VerticalAlignment=VerticalAlignment.Stretch,BorderThickness=new Thickness(1),BorderBrush=new SolidColorBrush(Color.FromRgb(65,85,103)),Background=new SolidColorBrush(Color.FromRgb(23,30,39)),CornerRadius=new CornerRadius(10)};panel.Children.Add(box);var title=Dialogs.Text(L("Working DLL configuration"),18);title.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));body.Children.Add(title);body.Children.Add(Dialogs.Text(L("Save only after testing the game. Includes detected DLSS DLLs and Streamline folders, not mod settings. Restore is manual and backs up current files."),13));var state=Dialogs.Text("",14);body.Children.Add(state);var row=new WrapPanel();body.Children.Add(row);var save=Button(row,"Save working configuration",async()=>{working=true;ModCenter.Busy=true;panel.IsEnabled=false;try{await Task.Run(()=>SavedComponents.Save(game));foreach(var scan in scans)scan();status.Text=L("Working configuration saved.");}catch(Exception ex){status.Text=L(ex.Message);}finally{working=false;ModCenter.Busy=false;panel.IsEnabled=true;}});save.Style=owner.TryFindResource("Primary") as Style;var restore=Button(row,"Restore saved configuration",async()=>await Run(progress=>SavedComponents.Restore(game)));restore.Style=owner.TryFindResource("RestoreAction") as Style;Action refresh=()=>{state.Text=SavedComponents.State(game);bool matches=false,valid=false;try{if(SavedComponents.Exists(game)){matches=SavedComponents.Differences(game)==0;valid=true;}}catch{}state.Foreground=matches?new SolidColorBrush(Color.FromRgb(230,172,80)):Brushes.LightGray;restore.IsEnabled=valid&&!matches;};scans.Add(refresh);refresh();}
 void AddRefresh(StackPanel card,Func<Task> refresh){refreshers.Add(refresh);var state=Dialogs.Text("",13);card.Children.Add(state);Button(card.Children.OfType<WrapPanel>().LastOrDefault() as Panel??card,"Check again",async()=>{if(working)return;working=true;try{await refresh();foreach(var scan in scans)scan();state.Text=L("Catalog check completed. See each component for its status.");}catch(Exception ex){state.Text=L(ex.Message);}finally{working=false;}});}
 StackPanel Details(StackPanel card){var existing=card.Children.OfType<Expander>().FirstOrDefault();if(existing!=null)return (StackPanel)existing.Content;var body=new StackPanel();card.Children.Add(new Expander{Header=L("Details"),Content=body,IsExpanded=false,Margin=new Thickness(0,8,0,4)});return body;}
 void refreshStatus(){status.Text=L("Checking updates…");}
 StackPanel Card(string name){var card=new StackPanel();var label=Dialogs.Text(name,15);label.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));card.Children.Add(label);panel.Children.Add(LayoutCards.Box(card));return card;}
 static ComboBox Combo(Panel parent,string name){parent.Children.Add(Dialogs.Text(L(name),12));var c=new ComboBox{MinWidth=180,MaxDropDownHeight=300,Margin=new Thickness(0,2,0,6),HorizontalAlignment=HorizontalAlignment.Stretch};System.Windows.Automation.AutomationProperties.SetName(c,L(name));parent.Children.Add(c);return c;}
 Button Button(Panel parent,string name,Action action){var b=new Button{Content=L(name),Margin=new Thickness(0,4,8,4),Padding=new Thickness(12,8,12,8)};b.HorizontalAlignment=HorizontalAlignment.Left;b.HorizontalContentAlignment=HorizontalAlignment.Left;parent.Children.Add(b);b.Click+=(s,e)=>{if(working||InlineOperation.IsBusy||ModCenter.Busy||RenoDxUi.IsBusy)return;try{action();}catch(Exception ex){status.Text=L(ex.Message);}};return b;}
 async Task Run(Func<Action<string>,DlssPlan> make){if(working||InlineOperation.IsBusy)return;working=true;ModCenter.Busy=true;panel.IsEnabled=false;try{Core.Closed(game);status.Text=L("Downloading and verifying…");status.BringIntoView();Action<string> progress=msg=>panel.Dispatcher.Invoke(new Action(()=>status.Text=L(msg)));var plan=await Task.Run(()=>make(progress));await InlineOperation.Apply(game,plan,status,()=>{foreach(var scan in scans)scan();changed();});}catch(Exception ex){status.Text=L(ex.Message);ActivityLog.Write(ex.Message);}finally{ModCenter.Busy=false;working=false;panel.IsEnabled=true;}}
 void ComponentRestores(StackPanel card,string id,string file){var button=Button(card,"Restore original",async()=>await Run(progress=>id=="native"?DlssLibraries.Restore(game,null,file):Streamline.Restore(game)));button.Style=owner.TryFindResource("RestoreAction") as Style;Action refresh=()=>{button.IsEnabled=ModInventory.Scan(game).Any(i=>i.Id==id&&(file==null||i.Library!=null&&i.Library.File.Equals(file,StringComparison.OrdinalIgnoreCase)));};scans.Add(refresh);refresh();}

 void Native(string file,string title){var card=Card("DLSS · "+title);var state=Dialogs.Text("",13);card.Children.Add(state);var targets=Combo(card,"Update destination");targets.DisplayMemberPath="DestinationLabel";var destination=Dialogs.Text("",13);card.Children.Add(destination);var versions=Combo(card,"Available version");versions.ItemsSource=DllCatalog.Local(file);versions.SelectedIndex=0;
  var info=Dialogs.Text(L("Local catalog · download required unless already cached."),12);Details(card).Children.Add(info);var row=new WrapPanel();card.Children.Add(row);((TextBlock)card.Children[card.Children.IndexOf(versions)-1]).Text=Selection;card.Children.Remove(versions);versions.Width=290;versions.Margin=new Thickness(0,4,8,4);versions.MinHeight=34;row.Children.Add(versions);
  var install=Button(row,"Install selected version",async()=>{var target=targets.SelectedItem as DlssLibrary;var version=versions.SelectedItem as DllDownload;if(target==null||version==null)return;await Run(progress=>{DlssLibraries.ValidateTarget(game,target);return DlssLibraries.Prepare(game,target,DllCatalog.Download(version,progress));});});
  ComponentRestores(card,"native",file);
  var detail=Details(card);var location=Dialogs.Text("",12);detail.Children.Add(location);scans.Add(()=>location.Text=String.Join("\n",DlssLibraries.Scan(game).Where(f=>f.File.Equals(file,StringComparison.OrdinalIgnoreCase)).Select(f=>f.Relative+" · "+Version(f.Version))));scans.Last()();var import=Button(detail,"Import DLL…",async()=>{var target=targets.SelectedItem as DlssLibrary;if(target==null)return;var pick=new Microsoft.Win32.OpenFileDialog{Filter="DLL|"+file};if(pick.ShowDialog(owner)==true){string source=pick.FileName;await Run(progress=>DlssLibraries.Prepare(game,target,source));}});
  Action scan=()=>{string old=(targets.SelectedItem as DlssLibrary)==null?null:((DlssLibrary)targets.SelectedItem).Path;var found=DlssLibraries.Scan(game).Where(f=>f.File.Equals(file,StringComparison.OrdinalIgnoreCase)).ToList();targets.ItemsSource=found;targets.SelectedItem=DlssLibraries.AutoTarget(game,found);install.IsEnabled=targets.SelectedItem!=null;targets.Visibility=Visibility.Collapsed;card.Children[card.Children.IndexOf(targets)-1].Visibility=targets.Visibility;state.Text=found.Count==0?L("Not detected. Select the correct game executable; installing a DLL alone does not add support."):Installed+": "+String.Join(" / ",found.Select(f=>Version(f.Version)).Distinct());state.ToolTip=String.Join("\n",found.Select(f=>f.Relative+" · "+Version(f.Version)));state.Foreground=found.Count>0?new SolidColorBrush(Color.FromRgb(230,172,80)):Brushes.LightGray;};Action selected=()=>{var target=targets.SelectedItem as DlssLibrary;import.IsEnabled=install.IsEnabled=target!=null;destination.Text=target==null?AutoHelp:AutoLabel+":\n"+target.Path+"\n"+AutoLabel;if(target!=null)state.Text=Installed+": "+Version(target.Version);else state.Text=targets.Items.Count==0?L("Not installed"):AutoHelp;if(targets.Items.Count==0)destination.Text=L("Not detected. Select the correct game executable; installing a DLL alone does not add support.");destination.ToolTip=target==null?null:target.Path;};scans.Add(()=>{scan();selected();});targets.SelectionChanged+=(s,e)=>selected();scan();selected();
  AddRefresh(card,async()=>{try{var items=await Task.Run(()=>DllCatalog.Fetch(file));string old=(versions.SelectedItem as DllDownload)==null?null:((DllDownload)versions.SelectedItem).Version;versions.ItemsSource=items;versions.SelectedItem=items.FirstOrDefault();info.Text=L("Online catalog verified.");}catch(Exception ex){info.Text=L("Online check failed. Local versions remain available.")+" "+ex.Message;}});
 }
 void StreamlineCard(){var card=Card("Streamline");var folders=Combo(card,"Update destination");var destination=Dialogs.Text("",13);card.Children.Add(destination);var versions=Combo(card,"Available version");versions.ItemsSource=Streamline.LocalVersions();versions.SelectedIndex=0;var info=Dialogs.Text(L("Local catalog · download required unless already cached."),12);Details(card).Children.Add(info);var row=new WrapPanel();card.Children.Add(row);((TextBlock)card.Children[card.Children.IndexOf(versions)-1]).Text=Selection;card.Children.Remove(versions);versions.Width=290;versions.Margin=new Thickness(0,4,8,4);versions.MinHeight=34;row.Children.Add(versions);
  var install=Button(row,"Install selected version",async()=>{string folder=folders.SelectedItem as string,version=versions.SelectedItem as string;if(folder==null||version==null)return;await Run(progress=>{Streamline.CheckTarget(game,folder);return Streamline.Prepare(game,folder,Streamline.Download(version,progress));});});
  ComponentRestores(card,"streamline",null);
  var detail=Details(card);var location=Dialogs.Text(Streamline.Summary(game),12);detail.Children.Add(location);scans.Add(()=>location.Text=Streamline.Summary(game));var import=Button(detail,"Import Streamline SDK ZIP",async()=>{string folder=folders.SelectedItem as string;if(folder==null)return;var pick=new Microsoft.Win32.OpenFileDialog{Filter="Streamline SDK|*.zip"};if(pick.ShowDialog(owner)==true){string zip=pick.FileName;await Run(progress=>Streamline.Prepare(game,folder,Streamline.Extract(zip)));}});
  var state=Dialogs.Text("",13);card.Children.Insert(1,state);Action scan=()=>{var paths=Streamline.Scan(game).Select(f=>Path.GetDirectoryName(f.Path)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();string old=folders.SelectedItem as string;folders.ItemsSource=paths;folders.SelectedItem=DlssLibraries.AutoFolder(game,paths);folders.Visibility=Visibility.Collapsed;card.Children[card.Children.IndexOf(folders)-1].Visibility=folders.Visibility;state.Text=paths.Count==0?L("Not installed"):Installed+": "+String.Join(" / ",Streamline.Scan(game).Select(f=>Version(f.Version)).Distinct());state.ToolTip=Streamline.Summary(game);state.Foreground=paths.Count>0?new SolidColorBrush(Color.FromRgb(230,172,80)):Brushes.LightGray;install.IsEnabled=folders.SelectedItem!=null;};Action selected=()=>{var folder=folders.SelectedItem as string;import.IsEnabled=install.IsEnabled=folder!=null;destination.Text=folder==null?AutoHelp:AutoLabel+":\n"+folder+"\n"+L("Only Streamline files in this folder will be updated.");state.Text=folder==null?(folders.Items.Count==0?L("Not installed"):AutoHelp):Installed+": "+String.Join(" / ",Streamline.Scan(game).Where(f=>String.Equals(Path.GetDirectoryName(f.Path),folder,StringComparison.OrdinalIgnoreCase)).Select(f=>Version(f.Version)).Distinct());};scans.Add(()=>{scan();selected();});folders.SelectionChanged+=(s,e)=>selected();scan();selected();
  AddRefresh(card,async()=>{try{var items=await Task.Run(()=>Streamline.Versions());string old=versions.SelectedItem as string;versions.ItemsSource=items;versions.SelectedItem=items.FirstOrDefault();info.Text=L("Online catalog verified.");}catch(Exception ex){info.Text=L("Online check failed. Local versions remain available.")+" "+ex.Message;}});
 }
 void NrCard(){var card=Card("Neural Rendering · DLSS 5");var state=Dialogs.Text("",13);card.Children.Add(state);var versions=Combo(card,"Available version");versions.ItemsSource=NrModels.Local();versions.SelectedIndex=0;bool chosen=false;versions.DropDownOpened+=(s,e)=>chosen=true;card.Loaded+=(s,e)=>{if(!chosen){var items=versions.Items.Cast<NrModel>();versions.SelectedItem=items.FirstOrDefault(m=>series()==40?m.Community:!m.Community);}};var info=Dialogs.Text(L("Community models: choose the variant for your GPU. This is separate from SR, RR and FG."),12);Details(card).Children.Add(info);var row=new WrapPanel();card.Children.Add(row);((TextBlock)card.Children[card.Children.IndexOf(versions)-1]).Text=Selection;versions.MinHeight=34;Button(row,"Install selected version",async()=>{var model=versions.SelectedItem as NrModel;if(model==null){status.Text=L("Select a version first.");return;}int gpu=series();NrModels.Compatible(model,gpu);DlssHardware.Detect().Validate(gpu,"");await Run(progress=>{NrModels.CheckModelChange(game);return NrModels.Prepare(game,NrModels.Download(model,progress),model);});});
  var removeNr=Button(card,"Remove Neural Rendering",async()=>await Run(progress=>ModCenter.RemoveGroup(game,"nr")));removeNr.Style=owner.TryFindResource("RestoreAction") as Style;scans.Add(()=>removeNr.IsEnabled=ModInventory.Scan(game).Any(i=>i.Id=="nr"));scans.Last()();
  Action scan=()=>{string path=Path.Combine(Path.GetDirectoryName(game.Exe),"nvngx_dlssnr.dll");bool exists=DlssCore.Pe64(path);state.Text=exists?Installed+": "+Version(System.Diagnostics.FileVersionInfo.GetVersionInfo(path).FileVersion):L("Not installed");state.Foreground=exists?new SolidColorBrush(Color.FromRgb(230,172,80)):Brushes.LightGray;};scans.Add(scan);scan();
  AddRefresh(card,async()=>{try{var items=await Task.Run(()=>NrModels.Fetch());string old=(versions.SelectedItem as NrModel)==null?null:((NrModel)versions.SelectedItem).Tag;versions.ItemsSource=items;versions.SelectedItem=items.FirstOrDefault(v=>v.Tag==old)??items.FirstOrDefault(m=>m.GpuSeries==series());info.Text=L("Community models: choose the variant for your GPU. This is separate from SR, RR and FG.");}catch(Exception ex){info.Text=L("Online check failed. Local versions remain available.")+" "+ex.Message;}});
 }
}
public static class LayoutCards {
 public static Border Box(UIElement content){var panel=content as Panel;if(panel!=null){var heading=panel.Children.OfType<TextBlock>().FirstOrDefault();if(heading!=null){heading.FontSize=17;heading.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));}}return new Border{Child=content,Padding=new Thickness(16),Margin=new Thickness(0,0,10,10),Background=new SolidColorBrush(Color.FromRgb(23,30,39)),BorderBrush=new SolidColorBrush(Color.FromRgb(44,54,67)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),VerticalAlignment=VerticalAlignment.Stretch};}
 public static Grid GridFor(UIElement[] cards){var grid=new Grid{HorizontalAlignment=HorizontalAlignment.Stretch};foreach(var card in cards)grid.Children.Add(card);int last=0;Action arrange=()=>{int cols=Math.Max(1,Math.Min(cards.Length,grid.ActualWidth>=1800?3:grid.ActualWidth>=1100?2:1));if(cols==last)return;last=cols;grid.ColumnDefinitions.Clear();grid.RowDefinitions.Clear();for(int i=0;i<cols;i++)grid.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<(cards.Length+cols-1)/cols;i++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});for(int i=0;i<cards.Length;i++){Grid.SetRow(cards[i],i/cols);Grid.SetColumn(cards[i],i%cols);}};grid.SizeChanged+=(s,e)=>arrange();arrange();return grid;}
 public static void OptiColumns(StackPanel parent,Border image,Border frames,Border customize){int index=parent.Children.IndexOf(image);parent.Children.Remove(image);parent.Children.Remove(frames);parent.Children.Remove(customize);parent.Children.Insert(index,GridFor(new UIElement[]{image,frames,customize}));}

 public static void Pair(StackPanel parent,Border a,Border b){a.VerticalAlignment=b.VerticalAlignment=VerticalAlignment.Top;int index=parent.Children.IndexOf(a);parent.Children.Remove(a);parent.Children.Remove(b);parent.Children.Insert(index,GridFor(new UIElement[]{a,b}));}
 public static void Group(StackPanel parent){var cards=parent.Children.OfType<Border>().Cast<UIElement>().ToArray();foreach(var card in cards)parent.Children.Remove(card);parent.Children.Add(GridFor(cards));}
 public static void Style(DependencyObject item){var text=item as TextBlock;if(text!=null){text.TextWrapping=TextWrapping.Wrap;if(text.Text!="ⓘ"&&text.Text!="⚠")text.Margin=new Thickness(0,4,0,8);var style=new Style(typeof(TextBlock),text.Style);var empty=new Trigger{Property=TextBlock.TextProperty,Value=""};empty.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Collapsed));style.Triggers.Add(empty);text.Style=style;}var button=item as Button;if(button!=null&&Convert.ToString(button.Content)!="?"){button.HorizontalAlignment=HorizontalAlignment.Left;button.HorizontalContentAlignment=HorizontalAlignment.Left;button.MinHeight=34;button.Padding=new Thickness(12,8,12,8);button.Margin=new Thickness(0,4,8,4);}var combo=item as ComboBox;if(combo!=null){combo.MinHeight=34;combo.Margin=new Thickness(0,4,8,4);}var panel=item as Panel;if(panel!=null)foreach(UIElement child in panel.Children)Style(child);var border=item as Border;if(border!=null&&border.Child!=null)Style(border.Child);var exp=item as Expander;if(exp!=null&&exp.Content is DependencyObject)Style((DependencyObject)exp.Content);}
 public static string Help {get{return RenoNr.T("Le tre categorie condividono riquadri, titoli, spazi, pulsanti e griglia adattiva a una, due o tre colonne. Versione installata distinta dalla versione da installare; percorsi nei dettagli. Opzioni NR nascoste per OptiScaler Standard. Riquadri adattivi e backup separato. Layout unificato: OptiScaler e DLL/Streamline mostrano subito versioni e comandi. Su finestre larghe i riquadri sono affiancati. Scegli la versione, poi premi Installa; per OptiScaler usa Applica impostazioni per salvare i parametri. Dettagli contiene importazioni e spiegazioni; I tre riquadri OptiScaler, Fluidità e Personalizza hanno dimensioni uguali: affiancati nelle finestre ampie, in colonna nelle finestre strette. Personalizza mostra sempre GPU, caricamento e tasti, senza menu da espandere. I comandi di rimozione e ripristino restano visibili. Il blu indica una scelta da applicare, il giallo un componente installato verificato.","All three categories share cards, headings, spacing, buttons and a responsive one, two or three-column grid. Installed version separated from the version to install; paths in Details. NR options hidden for OptiScaler Standard. Responsive cards and separate backup. Unified layout: OptiScaler and DLL/Streamline show versions and actions immediately. Cards sit side by side in wide windows. Choose a version, then Install; use Apply settings for OptiScaler parameters. Details holds imports and explanations; OptiScaler, Frame Generation and Customize use equal-sized cards: side by side in wide windows, stacked in narrow windows. Customize always displays GPU, loading and key settings without an expandable menu. Removal and restore controls remain visible. Blue means a pending choice; yellow means verified installed.","Las tres categorías comparten paneles, títulos, espacios, botones y cuadrícula adaptable de una, dos o tres columnas. Versión instalada separada de la versión para instalar; rutas en Detalles. Opciones NR ocultas con OptiScaler Standard. Paneles adaptables y copia separada. Diseño unificado: OptiScaler y DLL/Streamline muestran versiones y acciones. Paneles paralelos en ventanas amplias. Elige versión e instala; aplica los ajustes de OptiScaler con su botón. Detalles contiene importación y ayuda; OptiScaler, Frame Generation y Personalizar tienen el mismo tamaño: en fila en ventanas amplias, en columna en ventanas estrechas. Personalizar muestra siempre GPU, carga y teclas, sin menú desplegable. Eliminación y restauración visibles. Azul: elección pendiente; amarillo: instalación verificada.","Les trois catégories partagent cartes, titres, espacements, boutons et grille adaptative à une, deux ou trois colonnes. Version installée distincte de la version à installer ; chemins dans Détails. Options NR masquées pour OptiScaler Standard. Cartes adaptatives et sauvegarde séparée. Disposition unifiée : versions et actions OptiScaler et DLL/Streamline visibles. Cartes côte à côte sur grande fenêtre. Choisissez une version puis installez ; appliquez les paramètres OptiScaler avec le bouton dédié. Détails contient importation et aide ; OptiScaler, Frame Generation et Personnaliser ont les mêmes dimensions : en ligne sur grande fenêtre, en colonne sur petite fenêtre. Personnaliser affiche toujours GPU, chargement et touches, sans menu à déplier. Suppression et restauration visibles. Bleu : choix en attente ; jaune : installation vérifiée.","Alle drei Kategorien verwenden einheitliche Karten, Titel, Abstände, Schaltflächen und ein adaptives Raster mit einer, zwei oder drei Spalten. Installierte Version getrennt von der zu installierenden Version; Pfade unter Details. NR-Optionen bei OptiScaler Standard ausgeblendet. Adaptive Karten und separate Sicherung. Einheitliches Layout: Versionen und Aktionen für OptiScaler und DLL/Streamline sofort sichtbar. Karten stehen in breiten Fenstern nebeneinander. Version wählen und installieren; OptiScaler-Parameter mit Einstellungen anwenden speichern. Details enthält Import und Hilfe, OptiScaler, Frame Generation und Anpassen sind gleich groß: nebeneinander in breiten, untereinander in schmalen Fenstern. Anpassen zeigt GPU, Laden und Tasten immer ohne aufklappbares Menü. Entfernen und Wiederherstellen bleiben sichtbar. Blau: ausstehende Auswahl; Gelb: bestätigte Installation.","As três categorias compartilham painéis, títulos, espaços, botões e grade adaptável de uma, duas ou três colunas. Versão instalada separada da versão para instalar; caminhos em Detalhes. Opções NR ocultas para OptiScaler Standard. Painéis adaptáveis e backup separado. Layout unificado: versões e ações de OptiScaler e DLL/Streamline visíveis. Painéis lado a lado em janelas largas. Escolha a versão e instale; aplique os parâmetros OptiScaler com o botão correspondente. Detalhes contém importação e ajuda; OptiScaler, Frame Generation e Personalizar têm dimensões iguais: lado a lado em janelas largas, em coluna nas estreitas. Personalizar mostra sempre GPU, carregamento e teclas, sem menu expansível. Remoção e restauração visíveis. Azul: escolha pendente; amarelo: instalação verificada.");}}
